package dev.pathland.demo.quarkus;

import dev.pathland.demo.DemoTheme;
import dev.pathland.demo.ad.AdView;
import dev.pathland.demo.music.MusicPlayerView;
import dev.pathland.server.MountedApp;
import dev.pathland.server.PathlandApp;
import dev.pathland.view.core.ThemeData;
import dev.pathland.view.core.View;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Produces;
import jakarta.inject.Singleton;
import org.eclipse.microprofile.config.inject.ConfigProperty;

import java.util.function.Supplier;

/**
 * The Quarkus demo — the whole app. The Pathland starter provides SSR, the per-app
 * reserved {@code /<path>/_pathland/ws} delta transport, and per-session state; this
 * bean only supplies the root views (and the optional theme).
 *
 * <p>Two apps share the server: the {@link MusicPlayerView} at {@code /} and a small
 * {@link AdView} at {@code /ad}. The player's Now Playing pane embeds the {@code /ad}
 * app via a {@code ProxyView} (spec/PROXY.md) — a <b>same-server</b> proxy: the
 * player's session connects (over a loopback WebSocket) to the {@code /ad} app's own
 * {@code /ad/_pathland/ws} endpoint, remaps its node ids into a disjoint range, and
 * splices its subtree in — so the ad is fully interactive in place.
 */
@ApplicationScoped
public class QuarkusDemoApp {

    /**
     * The {@code /ad} app's base URL — the proxy origin. Defaults to this server's own
     * address; override with {@code pathland.demo.ad-url} (e.g. a different host/port).
     */
    @ConfigProperty(name = "pathland.demo.ad-url", defaultValue = "http://localhost:8080/ad")
    String adUrl;

    @Produces
    @Singleton
    PathlandApp mainApp() {
        return demoApp(() -> MusicPlayerView.make(adUrl));
    }

    /** The origin app mounted at {@code /ad}: a small title + button app the player proxies. */
    @Produces
    @Singleton
    MountedApp adApp() {
        return MountedApp.of("/ad", demoApp(AdView::new));
    }

    /** A fresh root per session (1:1 sessions own their own retained tree + state). */
    private static PathlandApp demoApp(Supplier<View> rootFactory) {
        return new PathlandApp() {
            @Override
            public View newRoot() {
                return rootFactory.get();
            }

            @Override
            public ThemeData theme() {
                return DemoTheme.adaptive();
            }
        };
    }
}
== quarkus demo props
quarkus.http.port=8080
quarkus.http.host=0.0.0.0
quarkus.log.category."dev.pathland".level=INFO

# --- Same-server proxy demo (spec/PROXY.md) ------------------------------------
# The music player at / embeds the small ad app mounted at /ad (this same server)
# as a sponsored slot in its Now Playing pane, via a ProxyView. This is the origin
# app's base URL the player proxies; point it at another host/port to proxy a
# remote app instead.
pathland.demo.ad-url=http://localhost:8080/ad

# --- Per-window id on the first request (issue #155) ---------------------------
# Opt the DOM client into the service worker that attaches the per-window id to
# top-level navigations, so the SSR renders the right persisted-state scope on the
# FIRST paint (instead of defaults that the live connection then corrects). The id
# never appears in the URL. Off by default; the worker is served at /_pathland/sw.js
# with Service-Worker-Allowed: / (root scope) and no-cache.
pathland.service-worker=true

# Static resources (the demo's media/icons are served from a disk extraction via
# DemoAssetsRoute, which also sends its own caching headers; this covers the rest
# of Quarkus's static resources, e.g. the DOM client bundle).
quarkus.http.static-resources.max-age=168h

# Pathland SSR debug comments: when true, every rendered HTML node is prefixed
# with a comment naming its component type and the modifiers applied, e.g.
#   <!-- #1 VStack: spacing=4, alignment=Fill -->
# Debugging aid — opt-in; the live /ws deltas are unaffected.
# pathland.debug-html=true

# --- Observability (issue #62) -------------------------------------------------
# Structured (JSON) console logging — the production-shaped reference app default.
quarkus.log.console.json.enabled=true
# Metrics: Micrometer counters/timers at pathland.* are exposed at /q/metrics
# (Prometheus); health at /q/health (smallrye-health). See pathland-observability.
#
# OpenTelemetry spans per frame send / event batch are OPT-IN. The starter wires the
# tracing decorator automatically when a Tracer is available, so to enable them just
# add the extension and point it at a collector:
#   <dependency>io.quarkus:quarkus-opentelemetry</dependency>
#   quarkus.otel.exporter.otlp.traces.endpoint=http://localhost:4317
# (the extension is intentionally NOT a dependency here, so local dev is quiet).

