-                frames.add(FrameCodec.decodeFrame(bytes));
-            } catch (RuntimeException ignored) {
-                // a partial/undecodable batch — keep scanning (defensive)
-            }
-            webSocket.request(1); // keep delivering messages
-            return null;
-        }
-
-        @Override
-        public java.util.concurrent.CompletionStage<?> onClose(WebSocket webSocket, int statusCode, String reason) {
-            peerCloseCodes.add(statusCode);
-            open = false;
-            System.err.println("[ws-session] peer closed status=" + statusCode + " reason=" + reason);
-            return null;
-        }
-
-        @Override
-        public void onError(WebSocket webSocket, Throwable error) {
-            open = false;
-            System.err.println("[ws-session] error " + error);
-        }
-    }
