            #[allow(non_snake_case, clippy::vec_init_then_push)]
            fn into_modifiers(self) -> Vec<Box<dyn ViewModifier>> {
                let ($($name,)+) = self;
                let mut list: Vec<Box<dyn ViewModifier>> = Vec::new();
                $( list.push(Box::new($name)); )+
                list
            }
        }
    };
}

